export interface ConnectorConfig {
  notionApiKey: string
  databaseId: string
  fetch?: typeof fetch
}

export interface PipedriveWebhookPayload {
  meta: {
    action: string
    entity: string
    entity_id: string
    timestamp: string
    version: string
    webhook_id: string
    webhook_owner_id: string
    attempt: number
    host: string
  }
  data: {
    add_time: string
    channel: string | null
    channel_id: string | null
    close_time: string | null
    creator_user_id: number
    currency: string
    custom_fields: Record<string, unknown>
    expected_close_date: string | null
    first_won_time: string | null
    id: number
    label_ids: number[]
    lost_reason: string | null
    lost_time: string | null
    org_id: number
    origin: string
    origin_id: string | null
    owner_id: number
    person_id: number
    pipeline_id: number
    probability: number | null
    stage_change_time: string | null
    stage_id: number
    status: string
    title: string
    update_time: string | null
    value: number
    visible_to: string
    won_time: string
  }
  previous: unknown | null
}

export interface NotionPageResponse {
  id: string
  created_time: string
  last_edited_time: string
  properties: Record<string, unknown>
}

export interface HandleResult {
  notionPageId: string
  dealId: number
}

function validatePayload(payload: unknown): asserts payload is PipedriveWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.meta || typeof p.meta !== 'object') {
    throw new Error('Missing meta object')
  }
  const meta = p.meta as Record<string, unknown>
  if (meta.action !== 'change') {
    throw new Error(`Unsupported meta.action: ${meta.action}`)
  }
  if (meta.entity !== 'deal') {
    throw new Error(`Unsupported meta.entity: ${meta.entity}`)
  }
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Missing data object')
  }
  const data = p.data as Record<string, unknown>
  if (data.status !== 'won') {
    throw new Error(`Deal status is not 'won': ${data.status}`)
  }
  if (typeof data.title !== 'string' || !data.title) {
    throw new Error('Missing or empty deal title')
  }
  if (typeof data.value !== 'number') {
    throw new Error('Missing or invalid deal value')
  }
  if (typeof data.owner_id !== 'number') {
    throw new Error('Missing or invalid owner_id')
  }
  if (typeof data.won_time !== 'string' || !data.won_time) {
    throw new Error('Missing or empty won_time')
  }
}

function buildNotionPageBody(payload: PipedriveWebhookPayload, databaseId: string): unknown {
  const { data } = payload
  return {
    parent: {
      database_id: databaseId
    },
    properties: {
      'Deal Title': {
        title: [
          {
            text: {
              content: data.title
            }
          }
        ]
      },
      'Deal Value': {
        number: data.value
      },
      Owner: {
        rich_text: [
          {
            text: {
              content: String(data.owner_id)
            }
          }
        ]
      },
      'Close Date': {
        date: {
          start: data.won_time
        }
      }
    }
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch
  validatePayload(payload)
  const typedPayload = payload as PipedriveWebhookPayload

  const body = buildNotionPageBody(typedPayload, config.databaseId)
  const response = await fetchImpl('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.notionApiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Notion API error: ${response.status} ${response.statusText} for POST https://api.notion.com/v1/pages - ${text}`
    )
  }

  const result = (await response.json()) as NotionPageResponse
  return {
    notionPageId: result.id,
    dealId: typedPayload.data.id
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, PipedriveWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      notionApiKey: 'test-notion-key',
      databaseId: 'test-database-id',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.notionPageId).toBe('page-id-generated-by-notion')
    expect(result.dealId).toBe(8)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let fetchMock: typeof fetch
  let calls: Array<{ method: string; url: string; body: string | undefined; json: unknown; headers: Headers }>

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetchMock = fetch
    calls = recordedCalls
    baseConfig = {
      notionApiKey: 'test-notion-key',
      databaseId: 'test-database-id',
      fetch: fetchMock
    }
  })

  it('creates a Notion page with correct field mapping on happy path', async () => {
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload
    const result = await handle(payload, baseConfig)

    expect(result.notionPageId).toBe('page-id-generated-by-notion')
    expect(result.dealId).toBe(8)
    expect(calls).toHaveLength(1)

    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.notion.com/v1/pages')
    expect(call.headers.get('authorization')).toBe('Bearer test-notion-key')
    expect(call.headers.get('notion-version')).toBe('2022-06-28')

    const body = call.json as Record<string, unknown>
    expect(body.parent).toEqual({ database_id: 'test-database-id' })
    const props = body.properties as Record<string, unknown>
    expect(props['Deal Title']).toEqual({
      title: [{ text: { content: 'Sample Org deal' } }]
    })
    expect(props['Deal Value']).toEqual({ number: 100 })
    expect(props.Owner).toEqual({
      rich_text: [{ text: { content: '12415231' } }]
    })
    expect(props['Close Date']).toEqual({
      date: { start: '2022-11-24T13:18:55Z' }
    })
  })

  it('throws descriptive error when required field title is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, title: '' }
    } as unknown as PipedriveWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing or empty deal title')
    expect(calls).toHaveLength(0)
  })

  it('throws descriptive error when required field value is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, value: undefined }
    } as unknown as PipedriveWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing or invalid deal value')
    expect(calls).toHaveLength(0)
  })

  it('throws descriptive error when required field owner_id is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, owner_id: undefined }
    } as unknown as PipedriveWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing or invalid owner_id')
    expect(calls).toHaveLength(0)
  })

  it('throws descriptive error when required field won_time is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, won_time: '' }
    } as unknown as PipedriveWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing or empty won_time')
    expect(calls).toHaveLength(0)
  })

  it('throws descriptive error when meta.action is not change', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      meta: { ...SOURCE_EXAMPLE.meta, action: 'create' }
    } as unknown as PipedriveWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow("Unsupported meta.action: create")
    expect(calls).toHaveLength(0)
  })

  it('throws descriptive error when data.status is not won', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, status: 'open' }
    } as unknown as PipedriveWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow("Deal status is not 'won': open")
    expect(calls).toHaveLength(0)
  })

  it('includes auth header with bearer token', async () => {
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload
    await handle(payload, baseConfig)

    const call = calls[0]
    expect(call.headers.get('authorization')).toBe('Bearer test-notion-key')
  })

  it('throws error with status code and endpoint on non-2xx response', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const config: ConnectorConfig = {
      notionApiKey: 'invalid-key',
      databaseId: 'test-database-id',
      fetch
    }
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow(
      'Notion API error: 401 Unauthorized for POST https://api.notion.com/v1/pages'
    )
    expect(errorCalls).toHaveLength(1)
  })

  it('throws error with status code and endpoint on 400 response', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'bad request' }, 400))
    const config: ConnectorConfig = {
      notionApiKey: 'test-notion-key',
      databaseId: 'invalid-database-id',
      fetch
    }
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow(
      'Notion API error: 400 Bad Request for POST https://api.notion.com/v1/pages'
    )
    expect(errorCalls).toHaveLength(1)
  })

  it('throws error with status code and endpoint on 429 rate limit', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'rate limited' }, 429))
    const config: ConnectorConfig = {
      notionApiKey: 'test-notion-key',
      databaseId: 'test-database-id',
      fetch
    }
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow(
      'Notion API error: 429 Too Many Requests for POST https://api.notion.com/v1/pages'
    )
    expect(errorCalls).toHaveLength(1)
  })
})

